#include <bitset>
#include <iostream>

int main() {
    // 7 is binary 000...0111
    std::bitset<10> flags1(7); 
    // Output: 0000000111
    std::cout << "N=10, Value=7: " << flags1 << "\n";

    // Value exceeds N, only LSBs are used (15 = 1111)
    std::bitset<3> flags2(15); 
    // Output: 111
    std::cout << "N=3, Value=15: " << flags2 << "\n";

    std::bitset<50> flags3; // Default: all zeros
    std::cout << "Default: " << flags3.to_string().substr(0, 10) << "...\n";
}
